import './gta-email-recovery-runtime.mjs';
import fs from 'node:fs';
import {SESv2Client,GetConfigurationSetCommand,GetConfigurationSetEventDestinationsCommand,UpdateConfigurationSetEventDestinationCommand,PutConfigurationSetVdmOptionsCommand} from '@aws-sdk/client-sesv2';
process.loadEnvFile('.env.ses.local');
const c=new SESv2Client({region:'us-east-2',maxAttempts:1}),name='saturn-crm-deliverability';
const before=await c.send(new GetConfigurationSetCommand({ConfigurationSetName:name}));
const {EventDestinations:destinations}=await c.send(new GetConfigurationSetEventDestinationsCommand({ConfigurationSetName:name}));
const destination=destinations.find(d=>d.Name==='saturn-crm-delivery-sns'&&d.Enabled&&d.SnsDestination?.TopicArn?.startsWith('arn:aws:sns:us-east-2:322694470585:'));
if(!destination)throw Error('Expected account SNS event destination missing');
const file='artifacts/partnership-pilot-3000-20261027/ses-tracking-change.json';
const report={at:new Date().toISOString(),before:{vdm:before.VdmOptions,destination},state:'planned'};
const save=()=>fs.writeFileSync(file,JSON.stringify(report,null,2));
if(!fs.existsSync(file))save();
const {Name,...options}=destination;
await c.send(new UpdateConfigurationSetEventDestinationCommand({ConfigurationSetName:name,EventDestinationName:Name,EventDestination:{...options,MatchingEventTypes:[...new Set([...options.MatchingEventTypes,'OPEN','CLICK'])]}}));
await c.send(new PutConfigurationSetVdmOptionsCommand({ConfigurationSetName:name,VdmOptions:{...before.VdmOptions,DashboardOptions:{EngagementMetrics:'ENABLED'}}}));
const after=await c.send(new GetConfigurationSetCommand({ConfigurationSetName:name}));
const events=await c.send(new GetConfigurationSetEventDestinationsCommand({ConfigurationSetName:name}));
const final=events.EventDestinations.find(d=>d.Name===Name);
if(!final?.MatchingEventTypes.includes('OPEN')||!final?.MatchingEventTypes.includes('CLICK')||after.VdmOptions?.DashboardOptions?.EngagementMetrics!=='ENABLED')throw Error('Tracking settings not verified');
if(JSON.stringify(after.SuppressionOptions)!==JSON.stringify(before.SuppressionOptions)||JSON.stringify(after.ArchivingOptions)!==JSON.stringify(before.ArchivingOptions))throw Error('Unrelated settings changed');
report.after={vdm:after.VdmOptions,eventTypes:final.MatchingEventTypes};report.state='verified';save();console.log(JSON.stringify({state:report.state,...report.after},null,2));
